		{
			title = "Summary",
			text = [=[Taretha Foxton was a girl of {link:durnholde-keep}Durnholde Keep{/link}, the daughter of {link:aedelas-blackmoore}Blackmoore{/link}'s servant Tammis Foxton. She was the closest thing to family that the young {link:thrall}Thrall{/link} ever knew. She wrote to him in secret when he was a slave, helped him escape, and paid for his freedom with her life.]=],
		},
		{
			title = "Significance",
			text = [=[{link:thrall}Thrall{/link} learned from {link:aedelas-blackmoore}Blackmoore{/link} what cruelty was. He learned from Taretha that humans could be good. Her memory is one reason the Warchief of the {link:horde}Horde{/link} has never hated all humankind.]=],
		},
		{
			title = "Deeds",
			text = [=[• As a child, she saw that the {link:orcs}orc{/link} infant could not eat the meat he was given, and so saved his life. Her mother nursed him.
• She hid notes inside the books she carried to {link:thrall}Thrall{/link}'s cell, and they wrote to each other for years.
• When Thrall fled {link:durnholde-keep}Durnholde{/link}, she raised a fire as a diversion and left him a cloak to pass the gate. She would not go with him, for fear of what {link:aedelas-blackmoore}Blackmoore{/link} would do to her family.
• She met Thrall in secret on the night before his army came to Durnholde. Blackmoore had her followed, and he had her killed.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No record says how Taretha's pendant came into the hands of the lords of {link:alterac-mountains}Alterac{/link}, nor where Taretha lies.]=],
		},
	},
	chapters = {
		{
			key = "taretha-s-gift",
			title = "Taretha's Gift",
			hint = "Recover the pendant that the Warchief desires.",
			unlock = {
				{ type = "quest", id = 508 },
			},
			text = [=[Long after her death, orcs sent by {link:thrall}Thrall{/link} came to {link:hillsbrad-foothills}Hillsbrad{/link} for a single pendant that had been hers. They found it around the neck of {link:elysa}Elysa{/link}, the mistress of {link:lord-aliden-perenolde}Aliden Perenolde{/link}. She gave it up gladly. The {link:orcs}orc{/link} who received it could not understand why the Warchief would spend so much for so small a thing.]=],
		},
	},
	mentions = {
		{
			text = "{link:aedelas-blackmoore}Blackmoore{/link}'s Legacy",
			unlock = {
				{ type = "quest", id = 506 },
			},
		},
		{
			text = "{link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}",
			unlock = {
				{ type = "quest", id = 507 },
			},
		},
		{
			text = "Taretha's Gift",
			unlock = {
				{ type = "quest", id = 508 },
			},
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "her friend, whom she called a brother" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "her master and her murderer" },
		{ id = "krusk", name = "Krusk", note = "recovered her pendant for the Warchief" },
	},
})

