	sections = {
		{
			title = "Summary",
			text = [=[Loremaster Dibbs is the scholar of {link:southshore}Southshore{/link}, an old man of books who lives nearer to the ruins of {link:alterac-mountains}Alterac{/link} than any other learned man of the {link:alliance}Alliance{/link}. He grieves for the libraries of that fallen kingdom. When a strange letter or a scrap of spellbound parchment comes down from the mountains, it is brought to him.]=],
