			title = "Significance",
			text = [=[Dibbs is {link:southshore}Southshore{/link}'s memory and its reader of riddles. Through his hands pass the lost books of {link:alterac-mountains}Alterac{/link} and the secret letters of the {link:syndicate}Syndicate{/link}. He knows the limits of his own learning, and he knows who to ask beyond them.]=],
