	sections = {
		{
			title = "Summary",
			text = [=[Apothecary Lydon is the {link:royal-apothecary-society}Royal Apothecary Society{/link}'s man in {link:tarren-mill}Tarren Mill{/link}. He is a gloomy soul who finds every day of undeath a misery. Only one thing lifts his spirits: the suffering of the living. His work is to make {link:sylvanas-windrunner}the Dark Lady{/link}'s new plague ready for {link:hillsbrad-foothills}Hillsbrad{/link}, and he does it with care and a terrible cheer.]=],
		},
		{
			title = "Significance",
			text = [=[{link:master-apothecary-faranell}Master Apothecary Faranell{/link} calls Lydon one of the Society's most dedicated and skilled members. His elixirs are where the plague meant for the {link:scourge}Scourge{/link} is first turned on humans.]=],
		},
		{
			title = "Deeds",
			text = [=[• He brews three elixirs, of Suffering, of Pain and of Agony, each deadlier than the last.
• He tests them on his frog, Umpi, on {link:farmer-ray}Farmer Ray{/link}'s dog, and on captured farmers.
• He brews a toxin for {link:apothecary-zamah}Apothecary Zamah{/link} against the {link:venture-company}Venture Company{/link} in {link:stonetalon-mountains}Stonetalon{/link}, from the blood of innocents taken from {link:syndicate}Syndicate{/link} mages.
• He studies the venom of the {link:witherbark-trolls}Witherbark trolls{/link}' spider god, and sends it to {link:master-apothecary-faranell}Faranell{/link}.
