Add({
	kind = "topic",
	id = "battle-of-hillsbrad",
	title = "Battle of Hillsbrad",
	category = "event",
	region = "hillsbrad-foothills",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 527 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Battle of Hillsbrad is the war that the {link:forsaken}Forsaken{/link} of {link:tarren-mill}Tarren Mill{/link} now wage on the humans of the foothills. Its aim is plain: to break the humans of {link:hillsbrad-foothills}Hillsbrad{/link} until the apothecaries finish the new plague, and then to raze {link:southshore}Southshore{/link}.]=],
		},
		{
			title = "The Campaign",
			text = [=[The order came from {link:varimathras}Varimathras{/link} to {link:high-executor-darthalia}High Executor Darthalia{/link}. When her scout at {link:southpoint-tower}Southpoint Tower{/link} sent word that the town was ripe, the attack began in stages.

• {b}The farms.{/b} The Deathguard struck the northern farms and their owners first, to cut {link:hillsbrad-foothills}Hillsbrad{/link}'s food.
• {b}The orchards.{/b} Peasants who fled into the southern orchards were hunted there.
• {b}The smithy.{/b} The blacksmith and his apprentices were killed, and the town's iron was carried off.
• {b}The council.{/b} The magistrate and council were marked for death, the town's charter for burning, and its registry for theft.
• {b}The mine.{/b} The foreman and miners of the {link:azurelode-mine}Azurelode Mine{/link} were attacked, so {link:sylvanas-windrunner}the Dark Lady{/link} could arm her soldiers from it.
• {b}{link:dun-garok}Dun Garok{/link}.{/b} Last came the siege of the dwarven fortress on {link:thoradin-s-wall}Thoradin's Wall{/link}.]=],
		},
		{
			title = "The Other Side",
			text = [=[The humans do not die quietly. Townsfolk of {link:hillsbrad-foothills}Hillsbrad{/link} have killed {link:forsaken}Forsaken{/link} guards, apothecaries and Deathstalkers, and ambushed the supplies sent from the {link:undercity}Undercity{/link}. {link:high-executor-darthalia}Darthalia{/link} keeps their names on a bounty list.]=],
		},
		{
			title = "The Apothecaries",
			text = [=[While the soldiers fight, {link:apothecary-lydon}Apothecary Lydon{/link} tests his elixirs on the dogs and the captured farmers of {link:hillsbrad-foothills}Hillsbrad{/link}. Each is meant as a step toward the plague that {link:sylvanas-windrunner}the Dark Lady{/link} has ordered.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "internment-camps",
	title = "Internment Camps",
	aliases = { "internment camp" },
	category = "structure",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[After the {link:second-war}Second War{/link}, the orcs who survived were not put to the sword. They were gathered into internment camps across {link:lordaeron}Lordaeron{/link}, guarded by the soldiers of the {link:alliance}Alliance{/link}. The camps were meant to be a place to hold a beaten enemy. They became something worse.]=],
		},
		{
			title = "The Lethargy",
			text = [=[Cut off from the demonic power that had driven them, the orcs in the camps grew listless and sick of spirit. Many simply sat behind the walls and did not try to leave. The humans who guarded them could not understand it. Some pitied them. Others profited from them.]=],
		},
		{
			title = "Durnholde",
			text = [=[The camps were ruled from {link:durnholde-keep}Durnholde Keep{/link} in {link:hillsbrad-foothills}Hillsbrad{/link}, under Lieutenant General {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. Blackmoore saw more than prisoners behind his walls. He saw an army that could be his, if an {link:orcs}orc{/link} he had raised himself were to lead it.]=],
		},
		{
			title = "The Liberation",
			text = [=[That {link:orcs}orc{/link} was {link:thrall}Thrall{/link}. He escaped {link:durnholde-keep}Durnholde{/link}, found the free clans and learned the ways of the shaman. With {link:orgrim-doomhammer}Orgrim Doomhammer{/link} at his side, he struck at the camps one by one and freed the orcs inside. Doomhammer fell in one of those battles. At last Thrall came to Durnholde itself, and the camps came to an end.]=],
		},
	},
})
